  hncarduniformenvelopefromrealizerndv.2 $e |- Z e. _V $.
  hncarduniformenvelopefromrealizerndv.3 $e |- ( WPP ->
    A. a A. r ( ( r We a /\ a C_ X ) ->
      T_c T_c T_c T_c T_c T_c Nc a <_c Nc Z ) ) $.
  hncarduniformenvelopefromrealizerndv.4 $e |-
    ( -. T_c T_c T_c T_c T_c T_c HNCard X <_c HNCard Z ->
      E. a E. r ( ( r We a /\ a C_ X ) /\
        HNCard Z <_c
          T_c T_c T_c T_c T_c T_c T_c T_c Nc a ) ) $.
  hncarduniformenvelopefromrealizerndv.5 $e |-
    -. HNCard Z <_c T_c T_c Nc Z $.

